proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=static_cache:100m inactive=10m max_size=1g;

server {
    listen 80;
    server_name cache.example.com;
    location / {
        proxy_cache static_cache;
        proxy_cache_valid 200 302 10m;
        proxy_pass http://127.0.0.1:8080;
    }
}

proxy_cache_path /var/cache/nginx keys_zone=api_cache:50m inactive=5m;

server {
    listen 80;
    server_name api.example.com;
    location / {
        proxy_cache api_cache;
        proxy_cache_bypass $http_authorization;
        proxy_no_cache $http_authorization;
        proxy_pass http://127.0.0.1:8080;
    }
}

proxy_cache_path /var/cache/nginx keys_zone=stale_cache:50m inactive=1h;

server {
    listen 80;
    server_name resilient.example.com;
    location / {
        proxy_cache stale_cache;
        proxy_cache_use_stale error timeout http_500 http_502 http_503 http_504 updating;
        proxy_cache_background_update on;
        proxy_pass http://127.0.0.1:8080;
    }
}

http {
    open_file_cache max=10000 inactive=30s;
    open_file_cache_valid 60s;
    open_file_cache_min_uses 2;
    open_file_cache_errors on;
    server {
        listen 80;
        server_name static.example.com;
        location / {
            root /var/www/static;
        }
    }
}

proxy_cache_path /var/cache/nginx keys_zone=vary_cache:50m;

server {
    listen 80;
    server_name vary.example.com;
    location / {
        proxy_cache vary_cache;
        proxy_cache_key "$scheme$host$request_uri$http_accept_encoding";
        proxy_pass http://127.0.0.1:8080;
    }
}

server {
    listen 80;
    server_name assets.example.com;
    location ~* \.(jpg|jpeg|png|gif|webp|svg|ico)$ {
        root /var/www/assets;
        expires 30d;
        add_header Cache-Control "public, immutable";
    }
    location ~* \.(css|js)$ {
        root /var/www/assets;
        expires 7d;
        add_header Cache-Control "public";
    }
}

http {
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    server {
        listen 80;
        server_name perf.example.com;
        location / {
            root /var/www/perf;
        }
    }
}

http {
    gzip on;
    gzip_comp_level 5;
    gzip_min_length 256;
    gzip_types text/plain text/css application/json application/javascript application/xml image/svg+xml;
    server {
        listen 80;
        server_name gz.example.com;
        location / {
            root /var/www/gz;
        }
    }
}

http {
    gzip on;
    gzip_types text/css application/javascript application/json;
    brotli on;
    brotli_comp_level 5;
    brotli_types text/css application/javascript application/json;
    server {
        listen 80;
        server_name br.example.com;
        location / {
            root /var/www/br;
        }
    }
}

server {
    listen 80;
    server_name uploads.example.com;
    client_max_body_size 1g;
    location /upload {
        proxy_pass http://127.0.0.1:8080;
        proxy_request_buffering off;
    }
}

fastcgi_cache_path /var/cache/nginx/fastcgi levels=1:2 keys_zone=php_cache:100m inactive=1h;

server {
    listen 80;
    server_name php.example.com;
    root /var/www/php;
    location ~ \.php$ {
        fastcgi_cache php_cache;
        fastcgi_cache_valid 200 1h;
        fastcgi_pass unix:/run/php/php8.2-fpm.sock;
        include fastcgi_params;
    }
}

proxy_cache_path /var/cache/nginx keys_zone=purge_cache:50m;

server {
    listen 80;
    server_name purge.example.com;
    location / {
        proxy_cache purge_cache;
        proxy_pass http://127.0.0.1:8080;
    }
    location ~ /purge(/.*) {
        allow 127.0.0.1;
        deny all;
        proxy_cache_purge purge_cache "$scheme$host$1";
    }
}

proxy_cache_path /var/cache/nginx keys_zone=mixed_cache:100m;

server {
    listen 80;
    server_name web.example.com;
    location ~* \.(css|js|png|jpg|woff2)$ {
        proxy_cache mixed_cache;
        proxy_cache_valid 200 7d;
        proxy_pass http://127.0.0.1:8080;
    }
    location / {
        proxy_pass http://127.0.0.1:8080;
        proxy_no_cache 1;
        add_header Cache-Control "no-store";
    }
}

proxy_cache_path /var/cache/nginx keys_zone=debug_cache:50m;

server {
    listen 80;
    server_name debug.example.com;
    location / {
        proxy_cache debug_cache;
        add_header X-Cache-Status $upstream_cache_status;
        proxy_pass http://127.0.0.1:8080;
    }
}

proxy_cache_path /var/cache/nginx keys_zone=micro:10m inactive=10s;

server {
    listen 80;
    server_name micro.example.com;
    location / {
        proxy_cache micro;
        proxy_cache_valid 200 1s;
        proxy_cache_lock on;
        proxy_pass http://127.0.0.1:8080;
    }
}

proxy_cache_path /var/cache/nginx keys_zone=method_cache:50m;

map $request_method $cache_ok {
    default 1;
    POST    0;
    PUT     0;
}

server {
    listen 80;
    server_name method.example.com;
    location / {
        proxy_cache method_cache;
        proxy_cache_bypass $cache_ok;
        proxy_no_cache $cache_ok;
        proxy_cache_valid 200 10m;
        proxy_pass http://127.0.0.1:8080;
    }
}

server {
    listen 80;
    server_name downloads.example.com;
    location /files/ {
        root /var/www;
        expires 1h;
        add_header Cache-Control "public, must-revalidate";
    }
}

upstream cached_backend {
    server 127.0.0.1:8080;
    keepalive 32;
}

server {
    listen 80;
    server_name keepcache.example.com;
    location / {
        proxy_pass http://cached_backend;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
    }
}

server {
    listen 80;
    server_name quiet.example.com;
    location ~* \.(png|jpg|css|js|woff2)$ {
        root /var/www/quiet;
        access_log off;
        expires 14d;
    }
}

proxy_cache_path /dev/shm/nginx_cache keys_zone=ram_cache:64m inactive=5m;

server {
    listen 80;
    server_name ranges.example.com;
    location /media/ {
        proxy_cache ram_cache;
        proxy_cache_valid 200 206 1h;
        slice 1m;
        proxy_set_header Range $slice_range;
        proxy_pass http://127.0.0.1:8080;
    }
}
